style:
/* 青霭 —— 灰绿通栏页眉，方头绿线标题，圆点条目 */

/* 页眉：负外边距吃掉纸张内边距，铺到纸边；上沿一条深绿粗线，下沿一条细线收边 */
.tw-qingai.layout-profile.resume-paper .paper-header {
  margin: -15mm -15mm 7mm;
  padding: 10mm 15mm 5.6mm;
  align-items: flex-start;
  gap: 6mm;
  background: #edf1ec;
  border-top: 0.7mm solid var(--paper-accent);
  border-bottom: 0.25mm solid color-mix(in srgb, var(--paper-accent) 45%, #fff);
  print-color-adjust: exact;
}

.tw-qingai.layout-profile.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

/* 证件照带白卡纸边：外圈一道极细的灰绿描边，打印出来才立得住 */
.tw-qingai.layout-profile.resume-paper .paper-photo {
  order: -1;
  width: 24mm;
  height: 32mm;
  border: 1.2mm solid #fff;
  border-radius: 0;
  box-shadow: 0 0 0 0.22mm #ccd8ce;
}

.tw-qingai.layout-profile.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #fff;
  color: var(--paper-accent);
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-qingai.layout-profile.resume-paper .paper-name {
  color: #1c2521;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.5);
  letter-spacing: 0.02em;
}

/* 姓名下压一条短绿线，参考稿里那条线只跟名字一样长 */
.tw-qingai.layout-profile.resume-paper .paper-name-row {
  padding-bottom: 2.4mm;
  background: linear-gradient(var(--paper-accent), var(--paper-accent)) left bottom / 16mm 0.8mm no-repeat;
  print-color-adjust: exact;
}

.tw-qingai.layout-profile.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qingai.layout-profile.resume-paper .paper-role {
  margin-top: 3mm;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.04);
  font-weight: 600;
  letter-spacing: 0.06em;
}

.tw-qingai.layout-profile.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.2mm 7mm;
  margin-top: 2.6mm;
  color: #57655b;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qingai.layout-profile.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.2mm;
}

.tw-qingai.layout-profile.resume-paper .paper-contact + .paper-contact::before {
  content: "|";
  left: -3.8mm;
  color: #bdcabe;
}

.tw-qingai.layout-profile.resume-paper .paper-contact__label {
  color: #7d8b81;
}

/* 标题：实心方块 + 绿字 + 通栏细线 */
.tw-qingai.layout-profile.resume-paper .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.2mm;
  padding-bottom: 1.3mm;
  border-bottom: 0.25mm solid color-mix(in srgb, var(--paper-accent) 38%, #fff);
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.04);
  letter-spacing: 0.14em;
}

.tw-qingai.layout-profile.resume-paper .paper-section__title::before {
  content: "";
  width: 2.4mm;
  height: 2.4mm;
  background: var(--paper-accent);
  print-color-adjust: exact;
}

.tw-qingai.layout-profile.resume-paper .paper-style-line .paper-section__title span::before {
  display: none;
}

.tw-qingai.layout-profile.resume-paper .paper-section__body {
  color: #33403a;
}

/* 条目：左侧空心圆，日期靠右 */
.tw-qingai.layout-profile.resume-paper .paper-item {
  position: relative;
  padding-left: 4.4mm;
}

.tw-qingai.layout-profile.resume-paper .paper-item::before {
  content: "";
  position: absolute;
  top: 2mm;
  left: 0;
  width: 2.1mm;
  height: 2.1mm;
  border: 0.26mm solid var(--paper-accent);
  border-radius: 50%;
  print-color-adjust: exact;
}

.tw-qingai.layout-profile.resume-paper .paper-item-head {
  gap: 4mm;
}

.tw-qingai.layout-profile.resume-paper .paper-item-title {
  color: #1c2521;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-qingai.layout-profile.resume-paper .paper-item-period {
  color: #7b8781;
  font-size: calc(var(--paper-base-size) * 0.84);
  letter-spacing: 0.04em;
}

.tw-qingai.layout-profile.resume-paper .paper-item-sub {
  gap: 0;
  color: #3d4b42;
}

.tw-qingai.layout-profile.resume-paper .paper-item-sub span + span::before {
  content: "";
  margin-right: 7mm;
}

/* 条目内的小点：用灰色实心圆点代替默认圆饼项目符号 */
.tw-qingai.layout-profile.resume-paper .paper-rich ul,
.tw-qingai.layout-profile.resume-paper .paper-rich ol {
  margin-top: 1mm;
  padding-left: 0;
  list-style: none;
}

.tw-qingai.layout-profile.resume-paper .paper-rich li {
  position: relative;
  margin: 0.8mm 0;
  padding-left: 3.4mm;
}

.tw-qingai.layout-profile.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.78em;
  left: 0.4mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: #96a598;
  print-color-adjust: exact;
}

.tw-qingai.layout-profile.resume-paper .paper-note {
  color: #56645a;
}

.tw-qingai.layout-profile.resume-paper .paper-note__tag {
  color: #22302a;
  font-weight: 600;
}

/* 主修课程回到正文读法：去掉胶囊边框与内边距 */
.tw-qingai.layout-profile.resume-paper .paper-note__tag {
  display: inline;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: none;
  color: #1d2c35;
  font-weight: 600;
  font-size: inherit;
}

.tw-qingai.layout-profile.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-qingai.layout-profile.resume-paper .paper-footer {
  border-top: 0.2mm solid #e0e6e0;
  color: #9aa69c;
}
